struct Parent: View {
    @State private var count = 0
    var body: some View {
        VStack {
            Child(count: count)
            Text("父视图: \(count)")
        }
    }
}

struct Child: View {
    @State private var count: Int
    init(count: Int) { _count = State(initialValue: count) }
    var body: some View {
        Button("加一") { count += 1 }
    }
}
